const payload = $input.first().json.body || $input.first().json;
const forbidden = ['bytes','pdf','path','nextcloud_folder_path','file_bytes'];
for (const k of Object.keys(payload)) {
  if (forbidden.includes(k)) {
    throw new Error('RED key forbidden in COA mapper: ' + k);
  }
}
return [{ json: {
  filename: payload.filename,
  sha256: payload.sha256,
  moisture_pct: payload.moisture_pct,
  mesh_pass: payload.mesh_pass,
  spec_moisture_max: payload.spec_moisture_max,
  spec_mesh_required: payload.spec_mesh_required
} }];

const b = $input.first().json;
const forbidden = ['bytes','pdf','path','nextcloud_folder_path','file_bytes'];
for (const k of Object.keys(b)) { if (forbidden.includes(k)) { throw new Error('RED key forbidden in COA compare: ' + k); } }
const coa_pass = Number(b.moisture_pct) <= Number(b.spec_moisture_max) && Boolean(b.mesh_pass) === Boolean(b.spec_mesh_required);
return [{ json: { coa_pass, moisture_pct: b.moisture_pct, mesh_pass: b.mesh_pass, coa_sha256: b.sha256 } }];
